{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Pimavanserin, a lipophilic piperidine-containing drug with high transferability to the query, has an absolute oral bioavailability of only 3% in humans, demonstrating that this scaffold class can be low-F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Saquinavir has a human absolute oral bioavailability of 4% and is subject to extensive first-pass metabolism, supporting a low-F outcome for the query's lipophilic, metabolically vulnerable acrylamide-piperidine drug class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "FK3453, a small-molecule amino-heteroaryl drug, showed unexpectedly poor oral bioavailability in humans due to metabolism, paralleling the query's amino-pyrazolopyrimidine structure and low-F risk.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "DX-9065a had a human oral bioavailability of only 2–3% and was advanced only as a parenteral agent, reinforcing that potent small molecules in this transfer set consistently fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Danavorexton required intravenous administration because of poor oral bioavailability, further supporting that piperidine-acyl/amide-containing drugs in this evidence set are consistently low-F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved human evidence, with high transferability, reports low absolute oral bioavailability (mostly 1–7%) for structurally and pharmacokinetically related molecules. The query's lipophilic piperidine-acrylamide and amino-heteroaromatic features do not provide a basis to expect F ≥ 20%; therefore the prediction is low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is provided.",
    "The retrieved evidence set contains no high-bioavailability comparator, so the prediction relies on consistent low-F analogues.",
    "The exact rate-limiting mechanism for the query (e.g., CYP3A first-pass metabolism vs solubility-limited absorption) is not directly measured in the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

